\begin{proposition}[the compact-subgroup criterion and the real formula]\hypertarget{tag-001B}{}\label{ari:C.7.2}
\StatementRecord{ari:C.7.2}{proved}{001B}{\SeriesRef{ari:C.7.1}, \SeriesRef{ari:eq:cp-periods}, \SeriesRef{ari:eq:cp-v}, \SeriesRef{ari:eq:cp-chi}; \citet[slides 5--8]{bertrand2017}}

For $P$ as in Statement \ref{ari:C.7.1}, $N(P)$ is algebraic if and only
if the fibre of $G_P$ above $P$ contains an algebraic point of
the maximal compact subgroup $G_P(\C)^c$.
For the family in the stated conventions, if $t>1$ is real, choose
$\tau=iT$, $T>1$, and the zero $\mu=1/2-iy$, $0<y<T/2$.
With $x=2y/T$, one has
\[
 N(P)^4=3^{3/4}(t-1)^{-1/4}
       \left|\frac{\vartheta_1(x,i/T)}{\eta(i/T)}\right|.
\]
\end{proposition}

\begin{proposition}[The factor $12$ with a fixed collar orientation]\hypertarget{tag-01SF}{}\label{inv:C3.2}\label{wb:lem:bcpr-degree-one-input}
\StatementRecord{inv:C3.2}{proved}{01SF}{\SeriesRef{inv:eq:C-collar-sum}, \SeriesRef{inv:C3.1}}

Use the marked cohomology class $\gamma$ dual to
$\hat\gamma$, the analytic peripheral generators and the lift relation of
[AC26, Section 7.5], and put
$p=12l_0-4l_1-3l_2=\pm1$.  Let $g_\gamma$ be the unique coherent
Leray class whose fibre image is $\gamma^{0,1}$.  Then
\begin{equation}\hypertarget{tag-01TE}{}\label{inv:eq:C-factor12}
\exp(12g_\gamma)=f^*\OO_{\Pone}(-p).
\end{equation}
For the standard data $(l_0,l_1,l_2)=(0,1,-1)$, this is
$\exp(12g_\gamma)=f^*\OO(1)$.  For the opposite value $p=1$,
the exponent representing $f^*\OO(1)$ is $-12g_\gamma$.
\end{proposition}

\begin{proposition}[Non-K\"ahler degrees and the precise degreewise statement]\hypertarget{tag-01SH}{}\label{inv:C3.4}
\StatementRecord{inv:C3.4}{proved}{01SH}{\SeriesRef{inv:C2.1}}

For $k=0,\ldots,6$ the non-K\"ahler degrees are
\begin{equation}\hypertarget{tag-01TC}{}\label{inv:eq:C-delta}
(\Delta^k)=(0,2,2+2h,4h,2+2h,2,0).
\end{equation}
If $h\ge1$, the two maps
$\bigoplus_{p+q=k}H^{p,q}_{BC}\to H^k_{\mathrm{dR}}(X;\C)
\to\bigoplus_{p+q=k}H^{p,q}_A$
are both isomorphisms exactly for $k=0,6$.
For the weaker assertion that a $d$-exact pure $d$-closed form of
degree $k$ is $\partial\bar\partial$-exact, the valid degrees are
$k=0,1,6$, and also $k=3,4$ if $h=0$.
\end{proposition}
